mapper.update:
UPDATE KEPRQDT
   SET CMS_CATLG_ID = #{CMS_CATLG_ID}
     , SND_CHK = 'N'
 WHERE BUYER = #{BUYER}
   AND QUOTATION_NO = #{QUOTATION_NO}
   AND QUOTATION_SEQ = #{QUOTATION_SEQ}
   AND REVISION = #{REVISION}

UPDATE ICOMBYIT
   SET CMS_CATLG_ID = #{CMS_CATLG_ID}
     , CHANGE_DATE = TO_CHAR(SYSDATE,'YYYYMMDD')
     , CHANGE_USER_ID = #{st_user_id}
     , CHANGE_USER_NAME = #{st_user_name_loc}
 WHERE BUYER = #{BUYER}
   AND BUYER_ITEM_NO = #{BUYER_ITEM_NO}

UPDATE EAI.IF_SEM_ITEM_DETAIL
   SET IF_FLAG = 'D'
      ,IF_MSG = #{P_MSG}||IF_MSG
 WHERE REQ_ID = #{QUOTATION_NO}
   AND COMP_ITEM_ID = #{COMP_ITEM_ID}

	    UPDATE KEPRQDT 
	       SET ATOB_UNIT_PRICE = 0 
	         , SND_CHK         = 'N'
	         , SND_DATM        = NULL
	         , BTOA_NEGO_PRICE = #{UNIT_PRICE}
	         , BTOA_END_DATE   = BTOA_END_DATE
	         , BTOA_END_TIME   = BTOA_END_TIME
	         , REJECT_REMARK   = #{st_user_name_loc} || ' - 품목IF재견적 처리 / ' || CASE WHEN TRIM( #{MASTER_IF_MSG} ) IS NOT NULL THEN #{MASTER_IF_MSG}
																		            WHEN TRIM( #{DETAIL_IF_MSG} ) IS NOT NULL THEN #{DETAIL_IF_MSG}
																		            WHEN TRIM( #{PRICE_IF_MSG} ) IS NOT NULL THEN #{PRICE_IF_MSG} 
																		            ELSE ' '
        																	  END
	         , RECV_FLAG       = 'GA' 
		 WHERE BUYER = #{BUYER}
		   AND QUOTATION_NO = #{QUOTATION_NO}
		   AND QUOTATION_SEQ = #{QUOTATION_SEQ}
		   AND REVISION = #{REVISION}
	       AND RECV_FLAG  IN ('GA') 
	       AND STATUS IN ('C','R')

    UPDATE KEPQTDT 
       SET BTOA_NEGO_PRICE =  #{UNIT_PRICE}
	 WHERE BUYER = #{BUYER}
	   AND QUOTATION_NO = #{QUOTATION_NO}
	   AND QUOTATION_SEQ = #{QUOTATION_SEQ}
	   AND REVISION = #{REVISION}
       AND STATUS = 'C'
